param(
    [string]$ProjectRoot = (Get-Location).Path
)

$ErrorActionPreference = "Stop"
$ProjectRoot = (Resolve-Path $ProjectRoot).Path

$SrcDir = Join-Path $ProjectRoot "src"
$AutomationDir = Join-Path $ProjectRoot "automation"
$DatabasePath = Join-Path $ProjectRoot "database\polymarket.db"
$SmartMoneyPath = Join-Path $SrcDir "smart_money_intelligence_engine.py"
$ElitePath = Join-Path $SrcDir "elite_wallet_intelligence_engine.py"
$RunnerPath = Join-Path $AutomationDir "run_smart_money_intelligence.ps1"
$LockPath = Join-Path $ProjectRoot "logs\automation\platform.lock"

foreach ($Required in @($SrcDir, $AutomationDir, $DatabasePath)) {
    if (-not (Test-Path $Required)) {
        throw "Required project item not found: $Required"
    }
}

if (Test-Path $LockPath) {
    throw "A platform automation lock exists. Finish the active platform run before installing this module."
}

$Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupDir = Join-Path $AutomationDir "backups\smart_money_intelligence_$Timestamp"
New-Item -ItemType Directory -Path $BackupDir -Force | Out-Null

Copy-Item $DatabasePath (Join-Path $BackupDir "polymarket.db") -Force
foreach ($File in @($SmartMoneyPath, $ElitePath, $RunnerPath)) {
    if (Test-Path $File) {
        Copy-Item $File (Join-Path $BackupDir ([IO.Path]::GetFileName($File))) -Force
    }
}

# Prevent Elite Wallet Intelligence from consuming its own derived tables.
if (Test-Path $ElitePath) {
    $EliteCode = Get-Content $ElitePath -Raw
    $EliteCode = $EliteCode.Replace(
        '"elite_wallet_intelligence", "elite_wallet_intelligence",',
        '"elite_wallet_intelligence",'
    )
    $EliteCode = $EliteCode.Replace(
        '"wallet_intelligence", "elite_wallet_intelligence",',
        '"wallet_intelligence", "elite_wallet_intelligence", "elite_wallet_",'
    )
    if ($EliteCode -notmatch '"elite_wallet_"') {
        $EliteCode = $EliteCode.Replace(
            '"wallet_intelligence",',
            '"wallet_intelligence", "elite_wallet_",'
        )
    }
    [System.IO.File]::WriteAllText(
        $ElitePath,
        $EliteCode,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

$Encoded = ""
$Bytes = [Convert]::FromBase64String($Encoded)
[System.IO.File]::WriteAllBytes($SmartMoneyPath, $Bytes)

$Runner = @'
param(
    [string]$ProjectRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
)

$ErrorActionPreference = "Stop"
Push-Location $ProjectRoot
try {
    python -m src.smart_money_intelligence_engine
    if ($LASTEXITCODE -ne 0) {
        throw "Smart Money Intelligence Engine failed."
    }
}
finally {
    Pop-Location
}
'@
[System.IO.File]::WriteAllText(
    $RunnerPath,
    $Runner,
    (New-Object System.Text.UTF8Encoding($false))
)

python -m py_compile $SmartMoneyPath
if ($LASTEXITCODE -ne 0) {
    throw "Smart Money Intelligence Engine failed Python compilation. Backup: $BackupDir"
}

if (Test-Path $ElitePath) {
    python -m py_compile $ElitePath
    if ($LASTEXITCODE -ne 0) {
        throw "Elite Wallet Intelligence source-loop patch failed compilation. Backup: $BackupDir"
    }
}

Write-Host ""
Write-Host "Running Elite Wallet Intelligence after source-loop repair..."
if (Test-Path $ElitePath) {
    python -m src.elite_wallet_intelligence_engine
    if ($LASTEXITCODE -ne 0) {
        throw "Elite Wallet Intelligence validation failed. Backup: $BackupDir"
    }
}

Write-Host ""
Write-Host "Running Smart Money Intelligence Engine v1.0..."
python -m src.smart_money_intelligence_engine
if ($LASTEXITCODE -ne 0) {
    throw "Smart Money Intelligence Engine failed. Backup: $BackupDir"
}

Write-Host ""
Write-Host "SMART MONEY INTELLIGENCE MODULE INSTALLED SUCCESSFULLY"
Write-Host "Engine: $SmartMoneyPath"
Write-Host "Runner: $RunnerPath"
Write-Host "Backup: $BackupDir"
Write-Host ""
Write-Host "Future isolated runs:"
Write-Host "  .\automation\run_smart_money_intelligence.ps1"
